def subarray_sum_k(nums: list[int], k: int) -> int:
    count, cumulative_sum = 0, 0
    sum_dict = {0: 1}
    for num in nums:
        cumulative_sum += num
        if cumulative_sum - k in sum_dict:
            count += sum_dict[cumulative_sum - k]
        sum_dict[cumulative_sum] = sum_dict.get(cumulative_sum, 0) + 1
    return count
```

